// Build the TAXO request page: email + one or more companies, each with its own brand list.

// Optional: if you switched the Brands API webhook to Header Auth, paste the same key here.
// Leave it empty ('') if the Brands API uses Basic Auth.
const TAXO_KEY = '';

const companies = $input.all()
  .map(i => i.json)
  .filter(c => c && c.company_name && c.company_id && c.mk_file_id)
  .map(c => ({ name: String(c.company_name), id: String(c.company_id), mk: String(c.mk_file_id) }))
  .sort((a, b) => a.name.localeCompare(b.name));

// "<" is escaped so no company name can break out of the <script> tag
const data = JSON.stringify(companies).replace(/</g, '\\u003c');
const key = JSON.stringify(TAXO_KEY).replace(/</g, '\\u003c');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>TAXO Request</title>
<style>
  :root { --bg:#f5f6f8; --card:#fff; --sub:#f9fafb; --text:#1d2330; --muted:#5d6675; --border:#d6dae1; --accent:#2a5bd7; --err:#b3261e; }
  @media (prefers-color-scheme: dark) {
    :root { --bg:#14171c; --card:#1d2129; --sub:#232833; --text:#e8eaee; --muted:#9aa3b2; --border:#343a46; --accent:#7ea2ff; --err:#ff8a80; }
  }
  * { box-sizing: border-box; }
  body { margin:0; background:var(--bg); color:var(--text); font:15px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; }
  .card { max-width:680px; margin:40px auto; background:var(--card); border:1px solid var(--border); border-radius:10px; padding:28px; }
  h1 { margin:0 0 4px; font-size:22px; }
  p.sub { margin:0 0 24px; color:var(--muted); }
  label.f { display:block; font-weight:600; margin:18px 0 6px; }
  .hint { color:var(--muted); font-size:13px; font-weight:400; }
  input[type=email], select, input[type=search] { width:100%; padding:9px 10px; border:1px solid var(--border); border-radius:6px; background:var(--card); color:var(--text); font:inherit; }
  .company-card { border:1px solid var(--border); background:var(--sub); border-radius:8px; padding:12px 14px; margin-top:12px; }
  .card-head { display:flex; align-items:baseline; gap:8px; margin-bottom:8px; }
  .card-head strong { flex:0 1 auto; }
  .card-head .ids { color:var(--muted); font-size:13px; flex:1; }
  button.remove { border:1px solid var(--border); background:var(--card); color:var(--text); border-radius:6px; padding:2px 10px; font:inherit; cursor:pointer; }
  .brand-list { max-height:240px; overflow:auto; border:1px solid var(--border); background:var(--card); border-radius:6px; padding:6px 10px; margin-top:8px; }
  .brand-list:empty { display:none; }
  label.brand { display:block; padding:3px 0; cursor:pointer; }
  .status { color:var(--muted); font-size:13px; margin-top:6px; }
  .sel-wrap { margin-top:10px; }
  .sel-head { font-size:13px; font-weight:600; color:var(--muted); margin-bottom:4px; }
  .sel-row { display:grid; grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto; gap:8px; align-items:center; padding:3px 0; }
  .sel-brand { overflow-wrap:anywhere; }
  .sel-arrow { color:var(--muted); }
  .sel-row input { width:100%; padding:6px 8px; border:1px solid var(--border); border-radius:6px; background:var(--card); color:var(--text); font:inherit; }
  .sel-row input.bad { border-color:var(--err); }
  button.sel-remove { border:0; background:none; color:var(--muted); font-size:18px; line-height:1; cursor:pointer; padding:2px 6px; }
  fieldset.rtype { border:0; padding:0; margin:0; }
  legend.f { font-weight:600; margin:18px 0 6px; padding:0; }
  label.radio { display:block; padding:3px 0; cursor:pointer; }
  #total { margin-top:18px; font-weight:600; }
  #form-error { color:var(--err); margin-top:10px; }
  #form-error:empty { display:none; }
  #submit-btn { margin-top:16px; width:100%; padding:11px; border:0; border-radius:6px; background:var(--accent); color:#fff; font:inherit; font-weight:600; cursor:pointer; }
  #submit-btn:disabled { opacity:.6; cursor:wait; }
</style>
</head>
<body>
<div class="card">
  <h1>TAXO Request</h1>
  <p class="sub">Request a taxonomy update. You'll be emailed when the ticket is completed.</p>
  <div id="dry-banner" hidden style="margin:0 0 16px;padding:10px 12px;border-radius:6px;background:#fff4d6;color:#6b4e00;border:1px solid #f0d58a;font-weight:600">🧪 DRY RUN MODE: no Jira ticket or log row will be created.</div>

  <form id="taxo-form" method="POST" action="taxo-request-submit">
    <label class="f" for="email">Requester Email</label>
    <input id="email" name="requesterEmail" type="email" placeholder="you@company.com" required>

    <fieldset class="rtype">
      <legend class="f">Request type</legend>
      <label class="radio"><input type="radio" name="requestType" value="new" required> New taxo <span class="hint">(brand not set up yet)</span></label>
      <label class="radio"><input type="radio" name="requestType" value="rerun"> Re-run taxo <span class="hint">(new products added under an existing brand)</span></label>
    </fieldset>

    <label class="f" for="company-picker">Companies <span class="hint">(add one or more, tick brands, then confirm each Epsilon Brand)</span></label>
    <select id="company-picker">
      <option value="">Add a company…</option>
    </select>
    <div id="company-cards"></div>

    <div id="total">No companies added yet.</div>
    <div id="form-error" role="alert"></div>

    <input type="hidden" name="selectionsJson">
    <button id="submit-btn" type="submit">Submit request</button>
  </form>
</div>

<script>
(function () {
  var COMPANIES = ${data};
  var TAXO_KEY = ${key};
  var form = document.getElementById('taxo-form');
  var picker = document.getElementById('company-picker');
  var cardsEl = document.getElementById('company-cards');
  var totalEl = document.getElementById('total');
  var errEl = document.getElementById('form-error');
  var btn = document.getElementById('submit-btn');
  var cards = {};   // keyed 'c' + index, so insertion order is kept

  // Dry-run mode: .../taxo-request?dryRun=1
  var DRY = new URLSearchParams(location.search).get('dryRun') === '1';
  if (DRY) {
    form.action = 'taxo-request-submit?dryRun=1';
    document.getElementById('dry-banner').hidden = false;
  }

  COMPANIES.forEach(function (c, i) {
    var o = document.createElement('option');
    o.value = String(i);
    o.textContent = c.name + '  (ID ' + c.id + ' · MK ' + c.mk + ')';
    picker.appendChild(o);
  });

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;   // textContent: never interpreted as HTML
    return e;
  }

  function checkedIn(state) { return Array.from(state.rows.keys()); }

  // Each ticked brand gets a row: AMAZON -> [amazon] (editable). A Map keeps tick order and is safe for any brand text.
  function addRow(state, brand, cb) {
    if (state.rows.has(brand)) return;
    var row = el('div', 'sel-row');
    var input = el('input');
    input.type = 'text';
    input.maxLength = 100;
    input.value = state.epsilon.has(brand) ? state.epsilon.get(brand) : brand.toLowerCase();
    input.setAttribute('aria-label', 'Epsilon Brand for ' + brand);
    input.addEventListener('input', function () {
      state.epsilon.set(brand, input.value);
      input.classList.toggle('bad', !input.value.trim());
    });
    var x = el('button', 'sel-remove', '\u00d7');
    x.type = 'button';
    x.setAttribute('aria-label', 'Unselect ' + brand);
    x.addEventListener('click', function () { cb.checked = false; removeRow(state, brand); refresh(state); });
    row.appendChild(el('span', 'sel-brand', brand));
    row.appendChild(el('span', 'sel-arrow', '\u2192'));
    row.appendChild(input);
    row.appendChild(x);
    state.selList.appendChild(row);
    state.rows.set(brand, { row: row, input: input });
    state.selWrap.hidden = false;
  }

  function removeRow(state, brand) {
    var r = state.rows.get(brand);
    if (!r) return;
    state.epsilon.set(brand, r.input.value);     // remember the edit if the brand is ticked again
    r.row.parentNode.removeChild(r.row);
    state.rows.delete(brand);
    state.selWrap.hidden = state.rows.size === 0;
  }

  function refresh(state) {
    state.statusEl.textContent = state.rows.size + ' of ' + state.total + ' selected';
    updateTotals();
  }

  function updateTotals() {
    var keys = Object.keys(cards), nBrands = 0;
    keys.forEach(function (k) { nBrands += checkedIn(cards[k]).length; });
    totalEl.textContent = keys.length
      ? nBrands + ' brand(s) selected across ' + keys.length + ' company(ies)'
      : 'No companies added yet.';
  }

  picker.addEventListener('change', function () {
    var idx = picker.value;
    picker.value = '';                               // reset so the next company can be added
    if (idx === '' || cards['c' + idx]) return;
    picker.options[Number(idx) + 1].disabled = true; // +1 skips the placeholder option
    addCompany(idx, COMPANIES[Number(idx)]);
  });

  function addCompany(idx, c) {
    var k = 'c' + idx;
    var card = el('div', 'company-card');
    var head = el('div', 'card-head');
    head.appendChild(el('strong', null, c.name));
    head.appendChild(el('span', 'ids', 'ID ' + c.id + ' · MK ' + c.mk));
    var rm = el('button', 'remove', 'Remove');
    rm.type = 'button';
    head.appendChild(rm);
    var filter = el('input');
    filter.type = 'search';
    filter.placeholder = 'Filter brands…';
    filter.disabled = true;
    var listEl = el('div', 'brand-list');
    var statusEl = el('div', 'status', 'Loading brands…');
    card.appendChild(head);
    card.appendChild(filter);
    card.appendChild(listEl);
    card.appendChild(statusEl);
    var selWrap = el('div', 'sel-wrap');
    selWrap.hidden = true;
    selWrap.appendChild(el('div', 'sel-head', 'Selected brand_attr \u2192 Epsilon Brand (edit if needed)'));
    var selList = el('div');
    selWrap.appendChild(selList);
    card.appendChild(selWrap);
    cardsEl.appendChild(card);

    var state = { company: c, listEl: listEl, statusEl: statusEl, selWrap: selWrap, selList: selList,
                  rows: new Map(), epsilon: new Map(), loaded: false, removed: false, total: 0 };
    cards[k] = state;
    updateTotals();

    rm.addEventListener('click', function () {
      state.removed = true;
      card.parentNode.removeChild(card);
      delete cards[k];
      picker.options[Number(idx) + 1].disabled = false;
      updateTotals();
    });

    filter.addEventListener('input', function () {
      var q = filter.value.toLowerCase();
      Array.prototype.forEach.call(listEl.children, function (l) {
        l.style.display = l.textContent.toLowerCase().indexOf(q) > -1 ? '' : 'none';
      });
    });

    listEl.addEventListener('change', function (ev) {
      var cb = ev.target;
      if (!cb || cb.type !== 'checkbox') return;
      if (cb.checked) addRow(state, cb.value, cb); else removeRow(state, cb.value);
      refresh(state);
    });

    var headers = { 'Accept': 'application/json' };
    if (TAXO_KEY) headers['X-Taxo-Key'] = TAXO_KEY;
    var url = 'taxo-brands?companyId=' + encodeURIComponent(c.id) + '&mkFileId=' + encodeURIComponent(c.mk);

    fetch(url, { headers: headers })
      .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .then(function (d) {
        if (state.removed) return;                   // company was removed while loading
        var brands = (d && d.brands) || [];
        if (!brands.length) { statusEl.textContent = 'No brands found for this company. Remove it to continue.'; return; }
        brands.forEach(function (b) {
          var label = el('label', 'brand');
          var cb = el('input');
          cb.type = 'checkbox';
          cb.value = b;
          label.appendChild(cb);
          label.appendChild(document.createTextNode(' ' + b));
          listEl.appendChild(label);
        });
        state.loaded = true;
        state.total = brands.length;
        filter.disabled = false;
        statusEl.textContent = '0 of ' + brands.length + ' selected';
      })
      .catch(function (e) {
        if (state.removed) return;
        statusEl.textContent = 'Could not load brands (' + e.message + '). Remove and re-add this company to retry.';
      });
  }

  form.addEventListener('submit', function (ev) {
    errEl.textContent = '';
    var keys = Object.keys(cards), selections = [], problems = [];
    keys.forEach(function (k) {
      var s = cards[k], picked = [];
      s.rows.forEach(function (r, brand) {
        var eb = r.input.value.trim();
        if (!eb) { r.input.classList.add('bad'); problems.push(s.company.name + ': Epsilon Brand missing for "' + brand + '"'); }
        picked.push({ brand: brand, epsilonBrand: eb });
      });
      if (!s.loaded) problems.push(s.company.name + ' (brands not loaded)');
      else if (!picked.length) problems.push(s.company.name + ' (no brands ticked)');
      else selections.push({ companyName: s.company.name, companyId: s.company.id, mkFileId: s.company.mk, brands: picked });
    });
    if (!keys.length) { ev.preventDefault(); errEl.textContent = 'Add at least one company.'; return; }
    if (problems.length) {
      ev.preventDefault();
      errEl.textContent = 'Please fix: ' + problems.join('; ') + '. Tick brands or remove the company.';
      return;
    }
    form.elements.namedItem('selectionsJson').value = JSON.stringify(selections);
    btn.disabled = true;               // prevents a double-click creating two tickets
    btn.textContent = 'Submitting…';
  });

  window.addEventListener('pageshow', function () { btn.disabled = false; btn.textContent = 'Submit request'; });
})();
</script>
</body>
</html>`;

return [{ json: { html } }];

// Validate the submission and prepare everything downstream nodes need.
// The page sends selectionsJson = [{ companyName, companyId, mkFileId, brands: [{ brand, epsilonBrand }, ...] }, ...]
const body = $json.body || {};
const MAX_COMPANIES = 25;
const JIRA_COMPONENT = 'Partner-Funded/Retail Media Network - Brand ID/Add';

const requesterEmail = String(body.requesterEmail || '').trim();
if (!/^[A-Za-z0-9._%+'-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(requesterEmail)) {
  throw new Error('Invalid requester email');
}

// New taxo or re-run. A page opened before this field existed sends nothing, so that falls back to 'new'.
const requestType = String(body.requestType || 'new').trim().toLowerCase();
if (!['new', 'rerun'].includes(requestType)) throw new Error('Invalid request type');
const isRerun = requestType === 'rerun';

let raw = [];
try { raw = JSON.parse(body.selectionsJson || '[]'); } catch (e) { raw = []; }
if (!Array.isArray(raw)) raw = [];

const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();   // trim + collapse inner spaces

const seen = new Set();
const companies = [];
for (const s of raw) {
  if (!s || typeof s !== 'object') continue;
  const companyId = clean(s.companyId);
  const mkFileId = clean(s.mkFileId);
  const companyName = clean(s.companyName) || companyId;
  if (!companyId || !mkFileId) throw new Error('A company selection is missing its ID or MK File ID');

  const key = companyId + '|' + mkFileId;
  if (seen.has(key)) continue;
  seen.add(key);

  const brands = [];
  const seenBrand = new Set();
  for (const b of (Array.isArray(s.brands) ? s.brands : [])) {
    // accepts { brand, epsilonBrand } or a plain string (older page version)
    const isObj = b && typeof b === 'object';
    const brand = clean(isObj ? b.brand : b);
    if (!brand || seenBrand.has(brand)) continue;
    seenBrand.add(brand);
    const epsilonBrand = clean(isObj ? b.epsilonBrand : '') || brand.toLowerCase();
    if (epsilonBrand.length > 100) throw new Error(`Epsilon Brand too long for "${brand}" (max 100 characters)`);
    brands.push({ brand, epsilonBrand });
  }
  if (brands.length === 0) throw new Error(`No brands selected for ${companyName}`);
  companies.push({ companyName, companyId, mkFileId, brands });
}

if (companies.length === 0) throw new Error('No companies were selected');
if (companies.length > MAX_COMPANIES) throw new Error(`Too many companies in one request (max ${MAX_COMPANIES})`);

// ---------- Ticket text, following the TAXO team's template ----------
const brandWord = n => (n === 1 ? 'brand' : 'brands');
const shortList = (arr, n = 3) => (arr.length <= n ? arr.join(', ') : arr.slice(0, n).join(', ') + ` +${arr.length - n} more`);
const names = companies.map(c => c.companyName);
const allBrands = [...new Set(companies.flatMap(c => c.brands.map(b => b.brand)))];
const brandCount = companies.reduce((n, c) => n + c.brands.length, 0);

// Everything that differs between "new" and "re-run" lives in this one object.
const T = isRerun
  ? {
      title: 'Re-run Taxo',
      introOne: (list) => `There are some more new products added under the ${brandWord(list.length)} ${list.join(', ')}. So we would like to rerun taxo.`,
      introMany: 'There are some more new products added under the following companies and brands. So we would like to rerun taxo.',
      ask: 'Could you please re-run taxo and populate Epsilon Brand'
    }
  : {
      title: 'Taxo',
      introOne: (list, c) => `We are in the process of setting up new partner-funded campaigns for ${c.companyName} for the following ${brandWord(list.length)}: ${list.join(', ')}`,
      introMany: 'We are in the process of setting up new partner-funded campaigns for the following companies and brands:',
      ask: 'Could you please populate Epsilon Brand'
    };

// Summary: "Acme Corp DE | Taxo for partner funded brand: AMAZON"
//          "Acme Corp DE | Re-run Taxo for partner funded brand: LEGO"   (Jira max 255 characters)
let jiraSummary = `${shortList(names)} | ${T.title} for partner funded ${brandWord(allBrands.length)}: ${shortList(allBrands)}`;
if (jiraSummary.length > 250) jiraSummary = jiraSummary.slice(0, 247) + '...';

const idBlock = c => [c.companyName, `mk_file_id: ${c.mkFileId}`, `company_id: ${c.companyId}`];
const mapping = b => `"${b.brand}" → "${b.epsilonBrand}"`;
const askMany = `${T.ask} as below wherever we receive the brand_attr in the product file / as the Client Brand?`;

const parts = [];
if (companies.length === 1) {
  const c = companies[0];
  const list = c.brands.map(b => b.brand);
  parts.push(T.introOne(list, c));
  parts.push(idBlock(c).join('\n'));
  if (c.brands.length === 1) {
    const b = c.brands[0];
    parts.push(`${T.ask} with "${b.epsilonBrand}" wherever we receive "${b.brand}" as the brand_attr in the product file / as the Client Brand?`);
  } else {
    parts.push(askMany + '\n' + c.brands.map(b => `- ${mapping(b)}`).join('\n'));
  }
} else {
  parts.push(T.introMany);
  for (const c of companies) {
    parts.push([...idBlock(c), `${c.brands.length === 1 ? 'Brand' : 'Brands'}: ${c.brands.map(b => b.brand).join(', ')}`].join('\n'));
  }
  parts.push(askMany + '\n' + companies.map(c => `- ${c.companyName}: ${c.brands.map(mapping).join(', ')}`).join('\n'));
}
const jiraDescription = parts.join('\n\n');

// Jira Server text fields hold ~32,767 characters; fail clearly instead of letting Jira reject it.
if (jiraDescription.length > 30000) {
  throw new Error('Too many brands for one Jira ticket (description over 30,000 characters). Split the request.');
}

return [{
  json: {
    requesterEmail,
    requestType,                                   // 'new' or 'rerun'
    requestTypeLabel: isRerun ? 'Re-run' : 'New',
    companies,
    companyCount: companies.length,
    brandCount,
    companyNames: names.join(', '),
    companyIds: companies.map(c => c.companyId).join(', '),
    mkFileIds: companies.map(c => c.mkFileId).join(', '),
    // Data Table log line: "Acme Corp DE (12345/67890): AMAZON→amazon, APPLE→apple | ..."
    logBrands: companies.map(c => `${c.companyName} (${c.companyId}/${c.mkFileId}): ${c.brands.map(b => `${b.brand}→${b.epsilonBrand}`).join(', ')}`).join(' | '),
    jiraSummary,
    jiraDescription,
    jiraComponent: JIRA_COMPONENT
  }
}];

// Preview of exactly what WOULD be sent to Jira. Nothing is written anywhere.
// Summary and description come from Parse Selection, the same source Create Issue uses.
const p = $('Parse Selection').first().json;

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dry run: TAXO Request</title>
<style>
  :root { --bg:#f5f6f8; --card:#fff; --text:#1d2330; --muted:#5d6675; --border:#d6dae1; --accent:#2a5bd7; --code:#f0f2f5; }
  @media (prefers-color-scheme: dark) { :root { --bg:#14171c; --card:#1d2129; --text:#e8eaee; --muted:#9aa3b2; --border:#343a46; --accent:#7ea2ff; --code:#262b35; } }
  body { margin:0; background:var(--bg); color:var(--text); font:15px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; }
  .card { max-width:760px; margin:40px auto; background:var(--card); border:1px solid var(--border); border-radius:10px; padding:28px; }
  .banner { padding:10px 12px; border-radius:6px; background:#fff4d6; color:#6b4e00; border:1px solid #f0d58a; font-weight:600; }
  h2 { font-size:14px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin:22px 0 6px; }
  pre { background:var(--code); border:1px solid var(--border); border-radius:6px; padding:12px; white-space:pre-wrap; word-break:break-word; margin:0; font-size:13px; }
  a { color:var(--accent); }
</style></head>
<body><div class="card">
  <div class="banner">🧪 DRY RUN: nothing was created in Jira or the taxo_requests table.</div>
  <p>${p.brandCount} brand(s) across ${p.companyCount} company(ies) → <strong>1 Jira ticket</strong></p>

  <h2>Jira fields</h2>
  <pre>Request type: ${esc(p.requestTypeLabel || 'New')}
Component: ${esc(p.jiraComponent)}</pre>

  <h2>Jira summary</h2>
  <pre>${esc(p.jiraSummary)}</pre>

  <h2>Jira description</h2>
  <pre>${esc(p.jiraDescription)}</pre>

  <h2>Would also log to taxo_requests</h2>
  <pre>issue_key: (new ticket key)
requester_email: ${esc(p.requesterEmail)}
brands: ${esc(p.logBrands)}
notified: false</pre>

  <p style="margin-top:22px"><a href="taxo-request?dryRun=1">Start another dry run</a></p>
</div></body></html>`;

return [{ json: { html } }];
